 52	class ToolboxView extends ComponentView {
 53	    static type = 'toolbox' as const;
 54	
 55	    _features: Dictionary<ToolboxFeature | UserDefinedToolboxFeature>;
 56	
 57	    _featureNames: string[];
 58	
 59	    render(
 60	        toolboxModel: ToolboxModel,
 61	        ecModel: GlobalModel,
 62	        api: ExtensionAPI,
 63	        payload: Payload & {
 64	            newTitle?: ToolboxFeatureOption['title']
 65	        }
 66	    ) {
 67	        const group = this.group;
 68	        group.removeAll();
 69	
 70	        if (!toolboxModel.get('show')) {
 71	            return;
 72	        }
 73	
 74	        const itemSize = +toolboxModel.get('itemSize');
 75	        const isVertical = toolboxModel.get('orient') === 'vertical';
 76	        const featureOpts = toolboxModel.get('feature') || {};
 77	        const features = this._features || (this._features = {});
 78	
 79	        const featureNames: string[] = [];
 80	        zrUtil.each(featureOpts, function (opt, name) {
 81	            featureNames.push(name);
 82	        });
 83	
 84	        (new DataDiffer(this._featureNames || [], featureNames))
 85	            .add(processFeature)
 86	            .update(processFeature)
 87	            .remove(zrUtil.curry(processFeature, null))
 88	            .execute();
 89	
 90	        // Keep for diff.
 91	        this._featureNames = featureNames;
 92	
 93	        function processFeature(newIndex: number, oldIndex?: number) {
 94	            const featureName = featureNames[newIndex];
 95	            const oldName = featureNames[oldIndex];
 96	            const featureOpt = featureOpts[featureName];
 97	            const featureModel = new Model(featureOpt, toolboxModel, toolboxModel.ecModel) as ToolboxFeatureModel;
 98	            let feature: ToolboxFeature | UserDefinedToolboxFeature;
 99	
100	            // FIX#11236, merge feature title from MagicType newOption. TODO: consider seriesIndex ?
101	            if (payload && payload.newTitle != null && payload.featureName === featureName) {
102	                featureOpt.title = payload.newTitle;
103	            }
104	
105	            if (featureName && !oldName) { // Create
106	                if (isUserFeatureName(featureName)) {
107	                    feature = {
108	                        onclick: featureModel.option.onclick,
109	                        featureName: featureName
110	                    } as UserDefinedToolboxFeature;
111	                }
112	                else {
113	                    const Feature = getFeature(featureName);
114	                    if (!Feature) {
115	                        return;
116	                    }
117	                    feature = new Feature();
118	                }
119	                features[featureName] = feature;
120	            }
121	            else {
122	                feature = features[oldName];
123	                // If feature does not exist.
124	                if (!feature) {
125	                    return;
126	                }
127	            }
128	            feature.uid = getUID('toolbox-feature');
129	            feature.model = featureModel;
130	            feature.ecModel = ecModel;
131	            feature.api = api;
132	
133	            const isToolboxFeature = feature instanceof ToolboxFeature;
134	            if (!featureName && oldName) {
135	                isToolboxFeature
136	                    && (feature as ToolboxFeature).dispose
137	                    && (feature as ToolboxFeature).dispose(ecModel, api);
138	                return;
139	            }
140	
141	            if (!featureModel.get('show') || (isToolboxFeature && (feature as ToolboxFeature).unusable)) {
142	                isToolboxFeature
143	                    && (feature as ToolboxFeature).remove
144	                    && (feature as ToolboxFeature).remove(ecModel, api);
145	                return;
146	            }
147	
148	            createIconPaths(featureModel, feature, featureName);
149	
150	            featureModel.setIconStatus = function (this: ToolboxFeatureModel, iconName: string, status: DisplayState) {
151	                const option = this.option;
152	                const iconPaths = this.iconPaths;
153	                option.iconStatus = option.iconStatus || {};
154	                option.iconStatus[iconName] = status;
155	                if (iconPaths[iconName]) {
156	                    (status === 'emphasis' ? enterEmphasis : leaveEmphasis)(iconPaths[iconName]);
157	                }
158	            };
159	
160	            if (feature instanceof ToolboxFeature) {
161	                if (feature.render) {
162	                    feature.render(featureModel, ecModel, api, payload);
163	                }
164	            }
165	        }
166	
167	        function createIconPaths(
168	            featureModel: ToolboxFeatureModel,
169	            feature: ToolboxFeature | UserDefinedToolboxFeature,
170	            featureName: string
171	        ) {
172	            const iconStyleModel = featureModel.getModel('iconStyle');
173	            const iconStyleEmphasisModel = featureModel.getModel(['emphasis', 'iconStyle']);
174	
175	            // If one feature has multiple icons, they are organized as
176	            // {
177	            //     icon: {
178	            //         foo: '',
179	            //         bar: ''
180	            //     },
181	            //     title: {
182	            //         foo: '',
183	            //         bar: ''
184	            //     }
185	            // }
186	            const icons = (feature instanceof ToolboxFeature && feature.getIcons)
187	                ? feature.getIcons() : featureModel.get('icon');
188	            const titles = featureModel.get('title') || {};
189	            let iconsMap: Dictionary<string>;
190	            let titlesMap: Dictionary<string>;
191	            if (zrUtil.isString(icons)) {
192	                iconsMap = {};
193	                iconsMap[featureName] = icons;
194	            }
195	            else {
196	                iconsMap = icons;
197	            }
198	            if (zrUtil.isString(titles)) {
199	                titlesMap = {};
200	                titlesMap[featureName] = titles as string;
201	            }
202	            else {
203	                titlesMap = titles;
204	            }
205	            const iconPaths: ToolboxFeatureModel['iconPaths'] = featureModel.iconPaths = {};
206	            zrUtil.each(iconsMap, function (iconStr, iconName) {
207	                const path = graphic.createIcon(
208	                    iconStr,
209	                    {},
210	                    {
211	                        x: -itemSize / 2,
212	                        y: -itemSize / 2,
213	                        width: itemSize,
214	                        height: itemSize
215	                    }
216	                ) as Displayable;  // TODO handling image
217	                path.setStyle(iconStyleModel.getItemStyle());
218	
219	                const pathEmphasisState = path.ensureState('emphasis');
220	                pathEmphasisState.style = iconStyleEmphasisModel.getItemStyle();
221	
222	                // Text position calculation
223	                // TODO: extract `textStyle` from `iconStyle` and use `createTextStyle`
224	                const textContent = new ZRText({
225	                    style: {
226	                        text: titlesMap[iconName],
227	                        align: iconStyleEmphasisModel.get('textAlign'),
228	                        borderRadius: iconStyleEmphasisModel.get('textBorderRadius'),
229	                        padding: iconStyleEmphasisModel.get('textPadding'),
230	                        fill: null,
231	                        font: getFont({
232	                            fontStyle: iconStyleEmphasisModel.get('textFontStyle'),
233	                            fontFamily: iconStyleEmphasisModel.get('textFontFamily'),
234	                            fontSize: iconStyleEmphasisModel.get('textFontSize'),
235	                            fontWeight: iconStyleEmphasisModel.get('textFontWeight')
236	                        }, ecModel)
237	                    },
238	                    ignore: true
239	                });
240	                path.setTextContent(textContent);
241	
242	                graphic.setTooltipConfig({
243	                    el: path,
244	                    componentModel: toolboxModel,
245	                    itemName: iconName,
246	                    formatterParamsExtra: {
247	                        title: titlesMap[iconName]
248	                    }
249	                });
250	
251	                (path as ExtendedPath).__title = titlesMap[iconName];
252	                (path as graphic.Path).on('mouseover', function () {
253	                    // Should not reuse above hoverStyle, which might be modified.
254	                    const hoverStyle = iconStyleEmphasisModel.getItemStyle();
255	                    const defaultTextPosition = isVertical
256	                        ? (
257	                            toolboxModel.get('right') == null && toolboxModel.get('left') !== 'right'
258	                                ? 'right' as const
259	                                : 'left' as const
260	                          )
261	                        : (
262	                            toolboxModel.get('bottom') == null && toolboxModel.get('top') !== 'bottom'
263	                                ? 'bottom' as const
264	                                : 'top' as const
265	                          );
266	                    textContent.setStyle({
267	                        fill: (iconStyleEmphasisModel.get('textFill')
268	                            || hoverStyle.fill || hoverStyle.stroke || tokens.color.neutral99) as string,
269	                        backgroundColor: iconStyleEmphasisModel.get('textBackgroundColor')
270	                    });
271	                    path.setTextConfig({
272	                        position: iconStyleEmphasisModel.get('textPosition') || defaultTextPosition
273	                    });
274	                    textContent.ignore = !toolboxModel.get('showTitle');
275	
276	                    // Use enterEmphasis and leaveEmphasis provide by ec.
277	                    // There are flags managed by the echarts.
278	                    api.enterEmphasis(this);
279	                })
280	                .on('mouseout', function () {
281	                    if (featureModel.get(['iconStatus', iconName]) !== 'emphasis') {
282	                        api.leaveEmphasis(this);
283	                    }
284	                    textContent.hide();
285	                });
286	                (featureModel.get(['iconStatus', iconName]) === 'emphasis' ? enterEmphasis : leaveEmphasis)(path);
287	
288	                group.add(path);
289	                (path as graphic.Path).on('click', zrUtil.bind(
290	                    feature.onclick, feature, ecModel, api, iconName
291	                ));
292	
293	                iconPaths[iconName] = path;
294	            });
295	        }
296	
297	        const refContainer = createBoxLayoutReference(toolboxModel, api).refContainer;
298	        const boxLayoutParams = toolboxModel.getBoxLayoutParams();
299	        const padding = toolboxModel.get('padding');
300	        const viewRect = getLayoutRect(
301	            boxLayoutParams,
302	            refContainer,
303	            padding
304	        );
305	        box(
306	            toolboxModel.get('orient'),
307	            group,
308	            toolboxModel.get('itemGap'),
309	            viewRect.width,
310	            viewRect.height
311	        );
312	        positionElement(
313	            group,
314	            boxLayoutParams,
315	            refContainer,
316	            padding
317	        );
318	
319	        // Render background after group is layout
320	        // FIXME
321	        group.add(listComponentHelper.makeBackground(group.getBoundingRect(), toolboxModel));
322	
323	        // Adjust icon title positions to avoid them out of screen
324	        isVertical || group.eachChild(function (icon: IconPath) {
325	            const titleText = (icon as ExtendedPath).__title;
326	            // const hoverStyle = icon.hoverStyle;
327	
328	            // TODO simplify code?
329	            const emphasisState = icon.ensureState('emphasis');
330	            const emphasisTextConfig = emphasisState.textConfig || (emphasisState.textConfig = {});
331	            const textContent = icon.getTextContent();
332	            const emphasisTextState = textContent && textContent.ensureState('emphasis');
333	            // May be background element
334	            if (emphasisTextState && !zrUtil.isFunction(emphasisTextState) && titleText) {
335	                const emphasisTextStyle = emphasisTextState.style || (emphasisTextState.style = {});
336	                const rect = textContain.getBoundingRect(
337	                    titleText, ZRText.makeFont(emphasisTextStyle)
338	                );
339	                const offsetX = icon.x + group.x;
340	                const offsetY = icon.y + group.y + itemSize;
341	
342	                let needPutOnTop = false;
343	                if (offsetY + rect.height > api.getHeight()) {
344	                    emphasisTextConfig.position = 'top';
345	                    needPutOnTop = true;
346	                }
347	                const topOffset = needPutOnTop ? (-5 - rect.height) : (itemSize + 10);
348	                if (offsetX + rect.width / 2 > api.getWidth()) {
349	                    emphasisTextConfig.position = ['100%', topOffset];
350	                    emphasisTextStyle.align = 'right';
351	                }
352	                else if (offsetX - rect.width / 2 < 0) {
353	                    emphasisTextConfig.position = [0, topOffset];
354	                    emphasisTextStyle.align = 'left';
355	                }
356	            }
357	        });
358	    }
359	
360	    updateView(
361	        toolboxModel: ToolboxModel,
362	        ecModel: GlobalModel,
363	        api: ExtensionAPI,
364	        payload: unknown
365	    ) {
366	        zrUtil.each(this._features, function (feature) {
367	            feature instanceof ToolboxFeature
368	                && feature.updateView && feature.updateView(feature.model, ecModel, api, payload);
369	        });
370	    }
371	
372	    // updateLayout(toolboxModel, ecModel, api, payload) {
373	    //     zrUtil.each(this._features, function (feature) {
374	    //         feature.updateLayout && feature.updateLayout(feature.model, ecModel, api, payload);
375	    //     });
376	    // },
377	
378	    remove(ecModel: GlobalModel, api: ExtensionAPI) {
379	        zrUtil.each(this._features, function (feature) {
380	            feature instanceof ToolboxFeature
381	                && feature.remove && feature.remove(ecModel, api);
382	        });
383	        this.group.removeAll();
384	    }
385	
386	    dispose(ecModel: GlobalModel, api: ExtensionAPI) {
387	        zrUtil.each(this._features, function (feature) {
388	            feature instanceof ToolboxFeature
389	                && feature.dispose && feature.dispose(ecModel, api);
390	        });
391	    }
392	}
